"""
Persistent Memory Filter for OpenWebUI — family edition (v3.1+aliases)
Single-file Filter with inlet (recall/commands/aliases) + outlet (store).
"""

import os
import re
import sqlite3
import hashlib
import logging
from urllib.parse import urlparse
from datetime import datetime, timezone, timedelta

import numpy as np
from numpy.linalg import norm

# ───────────────────────────── Config ─────────────────────────────
BASE_PATH = "/app/backend/data"
DB_PATH = os.path.join(BASE_PATH, "memories.db")
VAULT_DIR = os.path.join(BASE_PATH, "ObsidianVault/Memories")
os.makedirs(VAULT_DIR, exist_ok=True)

EMBED_MODEL_NAME = "BAAI/bge-m3"
EMBED_DIM = 1024

AUTO_RECALL_MIN_SIM = 0.55
EXPLICIT_RECALL_MIN_SIM = 0.35
KNOWLEDGE_AUTO_MIN_SIM = 0.50
KNOWLEDGE_EXPLICIT_MIN_SIM = 0.30

MAX_ITEMS = 3
MAX_KNOWLEDGE_ITEMS = 4
MAX_WORDS_PER_SUMMARY = 300
MAX_WORDS_PER_KNOWLEDGE = 220
RECALL_TOKEN_BUDGET = 1700
RECENCY_HALFLIFE_DAYS = 30
DEDUP_THRESHOLD = 0.92
SEARCH_DEDUP_THRESHOLD = 0.93

# Safety cap on stored knowledge size (chars). Set to 0 to disable.
MAX_KNOWLEDGE_CHARS = 200_000
# List snippet length for `knowledge list:` no-query view
LIST_SNIPPET_CHARS = 400

RECALL_BLOCK_MARKER = "Contextual Notes from previous discussion:"
HOUSEHOLD_USER_ID = "household"
GLOBAL_OWNER_ID = "global"

PRUNE_AGE_DAYS = 90
PRUNE_MAX_USE_COUNT = 0
SCHEMA_VERSION = 3

# Keys allowed in the `| key=value` pipe syntax.
# Anything else with `|` stays as part of the content (fixes table truncation).
ALLOWED_KV_KEYS = {"source", "confidence", "scope", "tags", "title", "note"}

_MUTED_USERS = set()
# Pending risky-action confirmations (in-memory, resets on restart)
_PENDING_CONFIRM = {}
CONFIRM_TTL_MIN = 10

logger = logging.getLogger("memory_filter")
logging.basicConfig(level=logging.INFO, format="[%(name)s] %(levelname)s %(message)s")


# ───────────────────────── Lazy model loader ──────────────────────
_EMB_MODEL = None
_EMB_LAST_FAIL_AT = None
_EMB_RETRY_AFTER_SEC = 60


def get_embedder():
    global _EMB_MODEL, _EMB_LAST_FAIL_AT
    if _EMB_MODEL is not None:
        return _EMB_MODEL if _EMB_MODEL is not False else None
    # retry policy: if previously failed, wait before retrying
    if _EMB_LAST_FAIL_AT is not None:
        elapsed = (datetime.now(timezone.utc) - _EMB_LAST_FAIL_AT).total_seconds()
        if elapsed < _EMB_RETRY_AFTER_SEC:
            return None
    try:
        from sentence_transformers import SentenceTransformer

        _EMB_MODEL = SentenceTransformer(EMBED_MODEL_NAME)
        logger.info(f"Loaded embedding model {EMBED_MODEL_NAME}")
        _EMB_LAST_FAIL_AT = None
        return _EMB_MODEL
    except Exception as e:
        logger.error(f"Failed to load embedding model: {e}")
        _EMB_MODEL = None
        _EMB_LAST_FAIL_AT = datetime.now(timezone.utc)
        return None


def embed(text: str):
    m = get_embedder()
    if m is None:
        return None
    v = m.encode(text, normalize_embeddings=False).astype(np.float32)
    n = norm(v)
    return v / n if n > 0 else v


# ─────────────────────────── DB helpers ───────────────────────────
def db_connect():
    conn = sqlite3.connect(DB_PATH)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=NORMAL")
    return conn


def init_db():
    try:
        with db_connect() as conn:
            conn.execute("""
                CREATE TABLE IF NOT EXISTS schema_version (
                    version INTEGER PRIMARY KEY
                )
            """)

            conn.execute("""
                CREATE TABLE IF NOT EXISTS memories (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    conversation_id TEXT,
                    user_msg TEXT,
                    assistant_msg TEXT,
                    summary TEXT,
                    embedding BLOB,
                    embedding_model TEXT,
                    embedding_dim INTEGER,
                    pinned INTEGER DEFAULT 0,
                    use_count INTEGER DEFAULT 0,
                    last_used_at DATETIME,
                    deleted_at DATETIME,
                    tags TEXT,
                    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
                )
            """)
            conn.execute("CREATE INDEX IF NOT EXISTS idx_user ON memories(user_id)")
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_user_active ON memories(user_id, deleted_at)"
            )

            cols = [
                r[1] for r in conn.execute("PRAGMA table_info(memories)").fetchall()
            ]
            if "tags" not in cols:
                conn.execute("ALTER TABLE memories ADD COLUMN tags TEXT")

            conn.execute("""
                CREATE TABLE IF NOT EXISTS knowledge_items (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    owner_user_id TEXT NOT NULL,
                    scope TEXT NOT NULL DEFAULT 'user',
                    title TEXT,
                    content TEXT NOT NULL,
                    source_url TEXT,
                    source_domain TEXT,
                    confidence REAL DEFAULT 0.7,
                    tags TEXT,
                    embedding BLOB,
                    embedding_model TEXT,
                    embedding_dim INTEGER,
                    pinned INTEGER DEFAULT 0,
                    use_count INTEGER DEFAULT 0,
                    last_used_at DATETIME,
                    deleted_at DATETIME,
                    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
                )
            """)
            conn.execute("""
                CREATE INDEX IF NOT EXISTS idx_knowledge_owner_active
                ON knowledge_items(owner_user_id, deleted_at)
            """)
            conn.execute("""
                CREATE INDEX IF NOT EXISTS idx_knowledge_scope_active
                ON knowledge_items(scope, deleted_at)
            """)

            conn.execute("""
                CREATE TABLE IF NOT EXISTS source_policies (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    owner_user_id TEXT NOT NULL,
                    domain TEXT NOT NULL,
                    policy TEXT NOT NULL,
                    note TEXT,
                    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(owner_user_id, domain)
                )
            """)
            conn.execute("""
                CREATE INDEX IF NOT EXISTS idx_source_owner_domain
                ON source_policies(owner_user_id, domain)
            """)

            row = conn.execute("SELECT MAX(version) FROM schema_version").fetchone()
            current = row[0] if row and row[0] is not None else 0
            if current < SCHEMA_VERSION:
                conn.execute(
                    "INSERT INTO schema_version(version) VALUES(?)",
                    (SCHEMA_VERSION,),
                )

            conn.commit()
    except Exception as e:
        logger.error(f"init_db failed: {e}")


init_db()


# ─────────────────────────── Utilities ────────────────────────────
def approx_tokens(text: str) -> int:
    return max(1, len(text) // 4)


def truncate_to_budget(text: str, max_tokens: int) -> str:
    if approx_tokens(text) <= max_tokens:
        return text
    char_budget = int(max_tokens * 4 * 0.9)
    clipped = text[:char_budget]
    if " " in clipped:
        clipped = clipped.rsplit(" ", 1)[0]
    return clipped + " … [truncated]"


def truncate_words(text: str, max_words: int) -> str:
    w = text.split()
    if len(w) <= max_words:
        return text
    return " ".join(w[:max_words]) + " … [truncated]"


def strip_recall_block(content: str) -> str:
    if RECALL_BLOCK_MARKER in content:
        m = re.search(r"User's Current Question:\s*\n(.*)$", content, re.S)
        if m:
            return m.group(1).strip()
    return content


def recency_weight(timestamp_str: str) -> float:
    try:
        ts = datetime.fromisoformat(timestamp_str.replace("Z", "+00:00"))
        if ts.tzinfo is None:
            ts = ts.replace(tzinfo=timezone.utc)
        age_days = (datetime.now(timezone.utc) - ts).total_seconds() / 86400
        return 0.5 ** (age_days / RECENCY_HALFLIFE_DAYS)
    except Exception:
        return 1.0


def get_user_id(__user__):
    if not __user__ or "id" not in __user__:
        return None
    return __user__["id"]


def get_conversation_id(body: dict) -> str:
    return body.get("chat_id") or body.get("id") or "unknown"


def normalize_domain(value: str) -> str:
    if not value:
        return ""
    value = value.strip().lower()
    if not value:
        return ""
    if "://" in value:
        try:
            host = urlparse(value).netloc.lower()
        except Exception:
            host = value
    else:
        host = value.split("/")[0].lower()
    host = host.split("@")[-1]
    host = host.split(":")[0]
    if host.startswith("www."):
        host = host[4:]
    return host.strip(".")


def parse_kv_pipe(text: str):
    """
    Whitelisted key=value pipe parser.

    Splits on '|'. The FIRST segment is always content.
    For subsequent segments: only treat them as key=value
    if `key` is in ALLOWED_KV_KEYS. Otherwise they stay
    as part of the content (preserves Markdown tables and
    code containing pipes).
    """
    if not text:
        return "", {}
    parts = text.split("|")
    content_segments = [parts[0]]
    kv = {}
    for p in parts[1:]:
        stripped = p.strip()
        if "=" in stripped:
            k, v = stripped.split("=", 1)
            k = k.strip().lower()
            if k in ALLOWED_KV_KEYS:
                kv[k] = v.strip()
                continue
        # Not a recognized field — keep the pipe and segment in content
        content_segments.append(p)
    content = "|".join(content_segments).strip()
    return content, kv


def scope_to_owner(scope: str, user_id: str) -> str:
    s = (scope or "user").strip().lower()
    if s == "household":
        return HOUSEHOLD_USER_ID
    if s == "global":
        return GLOBAL_OWNER_ID
    return user_id


def _set_pending_confirm(user_id: str, cmd: str):
    _PENDING_CONFIRM[user_id] = {
        "cmd": cmd,
        "expires_at": datetime.now(timezone.utc) + timedelta(minutes=CONFIRM_TTL_MIN),
    }


def _pop_pending_confirm_if_valid(user_id: str):
    item = _PENDING_CONFIRM.get(user_id)
    if not item:
        return None
    if datetime.now(timezone.utc) > item["expires_at"]:
        _PENDING_CONFIRM.pop(user_id, None)
        return None
    _PENDING_CONFIRM.pop(user_id, None)
    return item["cmd"]


def _is_confirm_yes(text: str) -> bool:
    t = text.strip().lower()
    return bool(
        re.match(r"^(confirm\s*:?\s*yes|confirm yes|yes)$", t)
        or t == "approve"
        or t == "confirm"
    )


def _extract_previous_content(messages: list) -> str:
    if not messages or len(messages) < 2:
        return ""
    for m in reversed(messages[:-1]):
        role = m.get("role")
        c = (m.get("content") or "").strip()
        if role in ("user", "assistant") and c:
            if not re.match(r"^(memory|knowledge|source|recall)\s*[:\-]", c, re.I):
                return c
    return ""


def _alias_to_core(last: str, messages: list, user_id: str):
    t = (last or "").strip()
    low = t.lower()

    if _is_confirm_yes(t):
        cmd = _pop_pending_confirm_if_valid(user_id)
        if cmd:
            return {"command": cmd}
        return {"reply": "No pending action to confirm."}

    if re.match(r"^(memory|knowledge|source)\b", low) or re.match(
        r"^recall\s*[:\-]\s*", low
    ):
        return {}

    m = re.match(r"^/remember\s+(.+)$", t, re.I | re.S)
    if m:
        return {"command": f"knowledge add: {m.group(1).strip()} | scope=user"}
    m = re.match(r"^/(house|household|home)\s+(.+)$", t, re.I | re.S)
    if m:
        return {"command": f"knowledge add: {m.group(2).strip()} | scope=household"}
    m = re.match(r"^/find\s+(.+)$", t, re.I | re.S)
    if m:
        return {"command": f"recall: {m.group(1).strip()}"}
    m = re.match(r"^/trust\s+([a-z0-9.-]+\.[a-z]{2,})$", low)
    if m:
        return {"command": f"source prefer: {m.group(1)}"}
    m = re.match(r"^/(avoid|unreliable)\s+([a-z0-9.-]+\.[a-z]{2,})$", low)
    if m:
        return {"command": f"source unreliable: {m.group(2)}"}
    m = re.match(r"^/block\s+([a-z0-9.-]+\.[a-z]{2,})$", low)
    if m:
        cmd = f"source block: {m.group(1)}"
        _set_pending_confirm(user_id, cmd)
        return {
            "reply": f"I'm about to block {m.group(1)}. Reply `confirm yes` within {CONFIRM_TTL_MIN} minutes to proceed."
        }

    if re.match(r"^(show|list)\s+(my\s+)?(memories|memory)$", low):
        return {"command": "memory list:"}
    if re.match(r"^(show|list)\s+(pinned|pinned memories|pinned memory)$", low):
        return {"command": "memory list pinned:"}
    if re.match(r"^(show|list)\s+(knowledge|notes|what you know)$", low):
        return {"command": "knowledge list:"}
    if re.match(r"^(show|list)\s+(source rules|sources|source policies)$", low):
        return {"command": "source list:"}

    m = re.match(r"^(what do you remember about|find|recall)\s+(.+)$", t, re.I | re.S)
    if m:
        return {"command": f"recall: {m.group(2).strip()}"}

    m = re.match(r"^(trust|prefer)\s+([a-z0-9.-]+\.[a-z]{2,})$", low)
    if m:
        return {"command": f"source prefer: {m.group(2)}"}
    m = re.match(
        r"^(avoid|unreliable|dont trust|don't trust)\s+([a-z0-9.-]+\.[a-z]{2,})$", low
    )
    if m:
        return {"command": f"source unreliable: {m.group(2)}"}
    m = re.match(r"^(block)\s+([a-z0-9.-]+\.[a-z]{2,})$", low)
    if m:
        cmd = f"source block: {m.group(2)}"
        _set_pending_confirm(user_id, cmd)
        return {
            "reply": f"I'm about to block {m.group(2)}. Reply `confirm yes` within {CONFIRM_TTL_MIN} minutes to proceed."
        }

    m = re.match(
        r"^(remember|save|note)\s+(this|that)?\s*(for\s+(the\s+)?(house|household))?\s*:\s*(.+)$",
        t,
        re.I | re.S,
    )
    if m:
        house = bool(m.group(5))
        content = (m.group(6) or "").strip()
        scope = "household" if house else "user"
        return {"command": f"knowledge add: {content} | scope={scope}"}

    if re.match(r"^(remember|save|note)\s+(this|that)$", low):
        prev = _extract_previous_content(messages)
        if not prev:
            return {
                "reply": "I need the content to save. Try: `Remember this: <text>`."
            }
        return {"command": f"knowledge add: {prev} | scope=user"}

    m = re.match(
        r"^(remember|save|note)\s+for\s+(the\s+)?(house|household)\s+(.+)$",
        t,
        re.I | re.S,
    )
    if m:
        return {"command": f"knowledge add: {m.group(4).strip()} | scope=household"}

    m = re.match(r"^(remember|save|note)\s+(.+)$", t, re.I | re.S)
    if m:
        return {"command": f"knowledge add: {m.group(2).strip()} | scope=user"}

    m = re.match(r"^(forget|delete|remove)\s+memory\s+(\d+)$", low)
    if m:
        cmd = f"memory forget: {m.group(2)}"
        _set_pending_confirm(user_id, cmd)
        return {
            "reply": f"I'm about to forget memory {m.group(2)}. Reply `confirm yes` within {CONFIRM_TTL_MIN} minutes to proceed."
        }
    m = re.match(r"^(forget|delete|remove)\s+knowledge\s+(\d+)$", low)
    if m:
        cmd = f"knowledge forget: {m.group(2)}"
        _set_pending_confirm(user_id, cmd)
        return {
            "reply": f"I'm about to forget knowledge item {m.group(2)}. Reply `confirm yes` within {CONFIRM_TTL_MIN} minutes to proceed."
        }

    return {}


# ─────────────────────────── Core search ──────────────────────────
def search_memories(query: str, user_id: str, min_sim: float, top_k: int = MAX_ITEMS):
    q_vec = embed(query)
    if q_vec is None:
        return []

    with db_connect() as conn:
        rows = conn.execute(
            "SELECT id, summary, embedding, timestamp, pinned, user_id "
            "FROM memories WHERE user_id IN (?, ?) AND deleted_at IS NULL "
            "AND embedding_model=? AND embedding_dim=?",
            (user_id, HOUSEHOLD_USER_ID, EMBED_MODEL_NAME, EMBED_DIM),
        ).fetchall()

    if not rows:
        return []

    scored = []
    for mid, summary, blob, ts, pinned, owner in rows:
        if not blob:
            continue
        try:
            emb = np.frombuffer(blob, dtype=np.float32)
            if emb.shape[0] != EMBED_DIM:
                continue
        except Exception:
            continue

        sim = float(np.dot(q_vec, emb))
        weighted = sim * recency_weight(ts)

        if pinned:
            weighted += 0.15
        if owner == HOUSEHOLD_USER_ID:
            weighted += 0.05

        if sim >= min_sim or pinned:
            scored.append((weighted, sim, mid, summary, emb))

    scored.sort(key=lambda x: x[0], reverse=True)

    selected, selected_ids = [], []
    for weighted, sim, mid, summary, emb in scored:
        if len(selected) >= top_k:
            break
        dup = False
        for _, _, _, _, prev_emb in selected:
            if float(np.dot(emb, prev_emb)) > SEARCH_DEDUP_THRESHOLD:
                dup = True
                break
        if not dup:
            selected.append((weighted, sim, mid, summary, emb))
            selected_ids.append(mid)

    if selected_ids:
        try:
            with db_connect() as conn:
                conn.executemany(
                    "UPDATE memories SET use_count=use_count+1, last_used_at=CURRENT_TIMESTAMP WHERE id=?",
                    [(i,) for i in selected_ids],
                )
                conn.commit()
        except Exception as e:
            logger.warning(f"Failed to update memory use stats: {e}")

    return [(sim, summary) for _, sim, _, summary, _ in selected]


def get_source_policy_map(user_id: str):
    result = {}
    rank = {GLOBAL_OWNER_ID: 1, HOUSEHOLD_USER_ID: 2, user_id: 3}
    owners = (GLOBAL_OWNER_ID, HOUSEHOLD_USER_ID, user_id)

    with db_connect() as conn:
        rows = conn.execute(
            "SELECT owner_user_id, domain, policy FROM source_policies "
            "WHERE owner_user_id IN (?, ?, ?)",
            owners,
        ).fetchall()

    tmp = {}
    for owner, domain, policy in rows:
        d = normalize_domain(domain)
        if not d:
            continue
        r = rank.get(owner, 0)
        if d not in tmp or r > tmp[d][0]:
            tmp[d] = (r, policy.strip().lower())

    for d, (_, p) in tmp.items():
        result[d] = p

    return result


def search_knowledge(
    query: str, user_id: str, min_sim: float, top_k: int = MAX_KNOWLEDGE_ITEMS
):
    q_vec = embed(query)
    if q_vec is None:
        return []

    policy_map = get_source_policy_map(user_id)

    with db_connect() as conn:
        rows = conn.execute(
            "SELECT id, title, content, source_domain, source_url, confidence, "
            "embedding, timestamp, pinned, owner_user_id "
            "FROM knowledge_items "
            "WHERE owner_user_id IN (?, ?, ?) AND deleted_at IS NULL "
            "AND embedding_model=? AND embedding_dim=?",
            (user_id, HOUSEHOLD_USER_ID, GLOBAL_OWNER_ID, EMBED_MODEL_NAME, EMBED_DIM),
        ).fetchall()

    if not rows:
        return []

    scored = []
    for (
        kid,
        title,
        content,
        domain,
        source_url,
        confidence,
        blob,
        ts,
        pinned,
        owner,
    ) in rows:
        if not blob:
            continue
        try:
            emb = np.frombuffer(blob, dtype=np.float32)
            if emb.shape[0] != EMBED_DIM:
                continue
        except Exception:
            continue

        d = normalize_domain(domain or source_url or "")
        pol = policy_map.get(d)
        if pol == "block":
            continue

        sim = float(np.dot(q_vec, emb))
        weighted = sim * recency_weight(ts)

        try:
            conf = float(confidence) if confidence is not None else 0.7
        except Exception:
            conf = 0.7
        conf = min(1.0, max(0.0, conf))
        weighted += (conf - 0.5) * 0.12

        if pinned:
            weighted += 0.12
        if owner == HOUSEHOLD_USER_ID:
            weighted += 0.04
        elif owner == GLOBAL_OWNER_ID:
            weighted += 0.02

        if pol == "prefer":
            weighted += 0.08
        elif pol == "unreliable":
            weighted -= 0.08

        if sim >= min_sim or pinned:
            scored.append((weighted, sim, kid, title, content, d, conf, pol, emb))

    scored.sort(key=lambda x: x[0], reverse=True)

    selected, selected_ids = [], []
    for row in scored:
        if len(selected) >= top_k:
            break
        emb = row[-1]
        dup = False
        for prev in selected:
            prev_emb = prev[-1]
            if float(np.dot(emb, prev_emb)) > SEARCH_DEDUP_THRESHOLD:
                dup = True
                break
        if not dup:
            selected.append(row)
            selected_ids.append(row[2])

    if selected_ids:
        try:
            with db_connect() as conn:
                conn.executemany(
                    "UPDATE knowledge_items SET use_count=use_count+1, last_used_at=CURRENT_TIMESTAMP WHERE id=?",
                    [(i,) for i in selected_ids],
                )
                conn.commit()
        except Exception as e:
            logger.warning(f"Failed to update knowledge use stats: {e}")

    out = []
    for _, sim, kid, title, content, d, conf, pol, _ in selected:
        out.append(
            {
                "sim": sim,
                "id": kid,
                "title": title or "",
                "content": content or "",
                "domain": d or "",
                "confidence": conf,
                "policy": pol or "normal",
            }
        )
    return out


def format_memory_recall(hits):
    lines = []
    for sim, summary in hits:
        summary = truncate_words(summary, MAX_WORDS_PER_SUMMARY)
        lines.append(f"(sim={round(sim,3)}) {summary}")
    return "\n---\n".join(lines)


def format_knowledge_recall(hits):
    lines = []
    for h in hits:
        body = truncate_words(h["content"], MAX_WORDS_PER_KNOWLEDGE)
        src = h["domain"] if h["domain"] else "unknown"
        policy_tag = ""
        if h["policy"] == "prefer":
            policy_tag = " ✅preferred"
        elif h["policy"] == "unreliable":
            policy_tag = " ⚠️unreliable"
        title = f"{h['title']} — " if h["title"] else ""
        lines.append(
            f"(sim={round(h['sim'],3)}, conf={round(h['confidence'],2)}) "
            f"{title}{body} [source: {src}{policy_tag}]"
        )
    return "\n---\n".join(lines)


def format_source_policy_summary(user_id: str):
    owners = (user_id, HOUSEHOLD_USER_ID, GLOBAL_OWNER_ID)
    with db_connect() as conn:
        rows = conn.execute(
            "SELECT owner_user_id, domain, policy FROM source_policies "
            "WHERE owner_user_id IN (?, ?, ?) "
            "ORDER BY owner_user_id, policy, domain",
            owners,
        ).fetchall()

    if not rows:
        return "No source policies set."

    prefer, unreliable, block = [], [], []
    for owner, domain, policy in rows:
        d = normalize_domain(domain)
        if not d:
            continue
        mark = (
            "🏠 "
            if owner == HOUSEHOLD_USER_ID
            else ("🌐 " if owner == GLOBAL_OWNER_ID else "")
        )
        item = f"{mark}{d}"
        p = policy.strip().lower()
        if p == "prefer":
            prefer.append(item)
        elif p == "unreliable":
            unreliable.append(item)
        elif p == "block":
            block.append(item)

    parts = []
    if prefer:
        parts.append("Prefer: " + ", ".join(prefer[:20]))
    if unreliable:
        parts.append("Unreliable: " + ", ".join(unreliable[:20]))
    if block:
        parts.append("Blocked: " + ", ".join(block[:20]))

    return " | ".join(parts) if parts else "No source policies set."


def build_context_block(query: str, mem_hits, know_hits, source_policy_text: str):
    sections = []
    if mem_hits:
        sections.append(f"{RECALL_BLOCK_MARKER}\n{format_memory_recall(mem_hits)}")
    if know_hits:
        sections.append(f"Knowledge Notes:\n{format_knowledge_recall(know_hits)}")
    sections.append(f"Source Policy:\n{source_policy_text}")
    sections.append(f"User's Current Question:\n{query}")
    return truncate_to_budget("\n\n".join(sections), RECALL_TOKEN_BUDGET)


