def cmd_knowledge_add(user_id: str, payload: str) -> str:
    content, kv = parse_kv_pipe(payload)
    content = content.strip()
    if not content:
        return (
            "Usage: knowledge add: <text> | source=<url/domain> | confidence=0.8 | "
            "scope=user|household|global | tags=a,b"
        )

    if MAX_KNOWLEDGE_CHARS and len(content) > MAX_KNOWLEDGE_CHARS:
        return (
            f"Content too large ({len(content)} chars). "
            f"Limit is {MAX_KNOWLEDGE_CHARS}. Split into smaller entries."
        )

    source = kv.get("source", "").strip()
    source_domain = normalize_domain(source)
    title = kv.get("title", "").strip() or None
    tags = kv.get("tags", "").strip() or None

    try:
        confidence = float(kv.get("confidence", "0.7"))
    except Exception:
        confidence = 0.7
    confidence = min(1.0, max(0.0, confidence))

    scope = kv.get("scope", "user").strip().lower()
    if scope not in {"user", "household", "global"}:
        scope = "user"
    owner = scope_to_owner(scope, user_id)

    emb_text = f"{title or ''}\n{content}\nsource:{source_domain}"
    v = embed(emb_text)
    if v is None:
        return "Embedding model unavailable."

    with db_connect() as conn:
        cur = conn.execute(
            "INSERT INTO knowledge_items(owner_user_id, scope, title, content, source_url, source_domain, confidence, tags, embedding, embedding_model, embedding_dim) "
            "VALUES (?,?,?,?,?,?,?,?,?,?,?)",
            (
                owner,
                scope,
                title,
                content,
                source if source else None,
                source_domain if source_domain else None,
                confidence,
                tags,
                v.tobytes(),
                EMBED_MODEL_NAME,
                EMBED_DIM,
            ),
        )
        new_id = cur.lastrowid
        conn.commit()

    owner_label = (
        "🏠 household"
        if owner == HOUSEHOLD_USER_ID
        else ("🌐 global" if owner == GLOBAL_OWNER_ID else "personal")
    )
    src_label = source_domain if source_domain else "no-source"
    return (
        f"Saved knowledge id={new_id} ({owner_label}, "
        f"conf={round(confidence,2)}, source={src_label}, len={len(content)})."
    )


def cmd_knowledge_list(user_id: str, query: str) -> str:
    query = (query or "").strip()
    if not query:
        with db_connect() as conn:
            rows = conn.execute(
                f"SELECT id, substr(content,1,{LIST_SNIPPET_CHARS}), source_domain, confidence, pinned, owner_user_id, timestamp, LENGTH(content) "
                "FROM knowledge_items "
                "WHERE owner_user_id IN (?, ?, ?) AND deleted_at IS NULL "
                "ORDER BY pinned DESC, id DESC LIMIT 20",
                (user_id, HOUSEHOLD_USER_ID, GLOBAL_OWNER_ID),
            ).fetchall()
        if not rows:
            return "No knowledge items stored."
        out_lines = []
        for kid, snip, dom, conf, p, owner, ts, full_len in rows:
            badge = (
                " 🏠"
                if owner == HOUSEHOLD_USER_ID
                else (" 🌐" if owner == GLOBAL_OWNER_ID else "")
            )
            pin = " 📌" if p else ""
            more = "…" if full_len and full_len > LIST_SNIPPET_CHARS else ""
            out_lines.append(
                f"[{kid}]{pin}{badge} {ts} — conf={round(conf or 0.0,2)} "
                f"src={dom or 'n/a'} len={full_len} — {snip}{more}"
            )
        return "\n".join(out_lines)

    hits = search_knowledge(query, user_id, min_sim=0.0, top_k=20)
    if not hits:
        return "No matching knowledge items."

    lines = []
    for h in hits:
        lines.append(
            f"[{h['id']}] sim={round(h['sim'],3)} conf={round(h['confidence'],2)} "
            f"src={h['domain'] or 'n/a'} — {truncate_words(h['content'],40)}"
        )
    return "\n".join(lines)


